<script setup lang="ts">
import {ref,computed} from 'vue';import {supabase} from '@/lib/supabase';import {useAuthStore} from '@/stores/auth';import {formatPen} from '@/lib/financeMoney';import {cashMethodLabel} from '@/lib/financeCash';import PaymentReceipt from './PaymentReceipt.vue';
interface Bundle {groupId:string;received:string|number;createdAt:string;collector:string;receipts:{paymentId:string;method:string;amount:string|number;number:string;reversed:boolean}[]}
const emit=defineEmits<{changed:[]}>();
const auth=useAuthStore(),opened=ref(false),busy=ref(false),error=ref(''),bundle=ref<Bundle|null>(null),receipt=ref<InstanceType<typeof PaymentReceipt>|null>(null),reason=ref(''),operation=ref('');
const canReverse=computed(()=>['ADMIN','SUPERADMIN'].includes(auth.role??'')&&bundle.value?.receipts.some(r=>!r.reversed));
async function open(id:string){opened.value=true;busy.value=true;error.value='';reason.value='';operation.value=crypto.randomUUID();try{const {data,error:e}=await supabase.rpc('finance_mixed_receipts',{p_group_id:id});if(e)throw e;bundle.value=data as Bundle;}catch{error.value='No se pudo obtener el detalle del pago mixto.';}finally{busy.value=false;}}
async function reverse(){if(!bundle.value||busy.value||reason.value.trim().length<5)return;busy.value=true;error.value='';try{const {error:e}=await supabase.rpc('finance_reverse_mixed',{p_operation_id:operation.value,p_group_id:bundle.value.groupId,p_reason:reason.value.trim()});if(e)throw e;const id=bundle.value.groupId;await open(id);emit('changed');}catch(e){error.value=e instanceof Error?e.message:'No se pudo anular el pago mixto. Reintenta la misma operación.';}finally{busy.value=false;}}
defineExpose({open});
</script>
<template><Teleport to="body"><div v-if="opened" class="modal-overlay"><section class="modal-panel finance-dialog" role="dialog" aria-modal="true" aria-labelledby="mixed-receipt-title"><div class="finance-dialog-head"><h2 id="mixed-receipt-title">Pago mixto</h2><button aria-label="Cerrar pago mixto" @click="opened=false">×</button></div><p v-if="busy">Cargando…</p><p v-if="error" class="finance-error" role="alert">{{error}}</p><template v-if="bundle"><p>Recibido <b>{{formatPen(String(bundle.received))}}</b> · {{bundle.collector}} · {{new Date(bundle.createdAt).toLocaleString('es-PE',{timeZone:'America/Lima'})}}</p><p class="finance-help">Cada medio conserva su constancia y su referencia dentro del mismo pago mixto.</p><div v-for="r in bundle.receipts" :key="r.paymentId" class="finance-history-line"><b>{{cashMethodLabel(r.method)}} · {{formatPen(String(r.amount))}}</b> · {{r.number}} <span v-if="r.reversed">· Anulado</span><button class="finance-link" @click="receipt?.open(r.paymentId)">Ver recibo</button></div><div v-if="canReverse"><label>Motivo de anulación<input v-model="reason" class="field-input" maxlength="500"></label><button class="btn-secondary" :disabled="busy||reason.trim().length<5" @click="reverse">Anular pago mixto</button></div></template></section></div></Teleport><PaymentReceipt ref="receipt"/></template>
